<script setup>
import { computed, ref } from 'vue';
import { Head, Link, useForm } from '@inertiajs/vue3';
import AcademyLayout from '@/Layouts/AcademyLayout.vue';
import Icon from '@/Components/AcademyIcon.vue';
const props = defineProps({ lesson: Object, modules: Array });
const source = computed(() => props.lesson);
const form = useForm({ module_id: source.value?.module_id || props.modules[0]?.id || '', title: source.value?.title || '', slug: source.value?.slug || '', summary: source.value?.summary || '', difficulty: source.value?.difficulty || 'beginner', estimated_minutes: source.value?.estimated_minutes || 15, objectives: source.value?.objectives || [''], prerequisites: source.value?.prerequisites || '', position: source.value?.position || 0, is_published: source.value?.is_published || false, sections: source.value?.sections?.map(({title,kind,body})=>({title,kind,body})) || [{ title: 'The concept', kind: 'explanation', body: '' }], code_examples: source.value?.code_examples?.map(({title,language,source_code,expected_output,explanation})=>({title,language,source_code,expected_output,explanation})) || [], exercises: source.value?.exercises?.map(({title,instructions,solution})=>({title,instructions,solution})) || [], tags: source.value?.tags || [], quiz: source.value?.quiz || null });
const tagsText = ref(form.tags.join(', '));
const locked = computed(() => !!source.value?.quiz_locked);
function save() { form.tags = tagsText.value.split(',').map(tag => tag.trim()).filter(Boolean); source.value ? form.put(route('admin.lessons.update', source.value.slug), { preserveScroll: true }) : form.post(route('admin.lessons.store')); }
function move(items, index, direction) { const next = index + direction; if (next >= 0 && next < items.length) [items[index], items[next]] = [items[next], items[index]]; }
function addQuestion() { form.quiz.questions.push({ prompt: '', explanation: '', options: ['', '', '', ''], correct_index: 0 }); }
</script>
<template><Head :title="source ? 'Edit lesson' : 'Create lesson'" /><AcademyLayout title="Lesson editor"><div class="page-heading"><div><span class="eyebrow">ACADEMY STUDIO / LESSON EDITOR</span><h1>{{ source ? 'Refine a lightbulb moment.' : 'Teach something that matters.' }}</h1><p>Write plain text. Code belongs in examples. Every save is validated on the server.</p></div><Link :href="route('admin.index')" class="button secondary">Back to content</Link></div><form class="editor-form" @submit.prevent="save"><div v-if="Object.keys(form.errors).length" class="error-list" role="alert"><strong>Please correct these fields:</strong><ul><li v-for="(error,key) in form.errors" :key="key">{{ key }}: {{ error }}</li></ul></div><section class="panel editor-section"><div class="section-heading"><h2>Lesson details</h2><span class="eyebrow">01</span></div><div class="editor-fields"><label class="field wide-field">Title<input v-model="form.title" required maxlength="200" /></label><label class="field">URL slug<input v-model="form.slug" required pattern="[a-z0-9]+(-[a-z0-9]+)*" /></label><label class="field">Module<select v-model="form.module_id" required><option v-for="module in modules" :key="module.id" :value="module.id">{{ module.title }}</option></select></label><label class="field wide-field">Summary<textarea v-model="form.summary" rows="3" required maxlength="2000" /></label><label class="field">Difficulty<select v-model="form.difficulty"><option>beginner</option><option>intermediate</option><option>advanced</option></select></label><label class="field">Estimated minutes<input v-model="form.estimated_minutes" type="number" min="1" max="600" required /></label><label class="field">Position in module<input v-model="form.position" type="number" min="0" max="10000" required /></label><label class="field">Tags, separated by commas<input v-model="tagsText" placeholder="php, interfaces, dependency injection" /></label><label class="field wide-field">Prerequisites<textarea v-model="form.prerequisites" rows="2" /></label></div><div class="section-heading"><h3>Learning objectives</h3><button type="button" class="small-button" @click="form.objectives.push('')">Add objective +</button></div><div v-for="(_,index) in form.objectives" :key="index" class="flex gap-2 mb-3"><input v-model="form.objectives[index]" class="flex-1 p-2 text-xs min-w-0" required :aria-label="`Objective ${index + 1}`" /><button type="button" class="small-button danger" @click="form.objectives.splice(index,1)">Remove</button></div></section><section class="panel editor-section"><div class="section-heading"><h2>Teaching sections</h2><button type="button" class="small-button" @click="form.sections.push({title:'',kind:'explanation',body:''})">Add section +</button></div><div v-for="(section,index) in form.sections" :key="index" class="editor-item"><div class="item-actions"><span>SECTION {{ index + 1 }}</span><div><button type="button" class="small-button" :disabled="index === 0" @click="move(form.sections,index,-1)">↑</button><button type="button" class="small-button" :disabled="index === form.sections.length-1" @click="move(form.sections,index,1)">↓</button><button type="button" class="small-button danger" @click="form.sections.splice(index,1)">Remove</button></div></div><div class="editor-fields"><label class="field">Heading<input v-model="section.title" required /></label><label class="field">Type<select v-model="section.kind"><option v-for="kind in ['explanation','analogy','walkthrough','mistakes','interview','takeaways','security','testing']" :key="kind">{{ kind }}</option></select></label></div><label class="field">Explanation<textarea v-model="section.body" required rows="8" /></label></div></section><section class="panel editor-section"><div class="section-heading"><h2>Code examples</h2><button type="button" class="small-button" @click="form.code_examples.push({title:'',language:'php',source_code:'<?php\n',expected_output:'',explanation:''})">Add example +</button></div><div v-for="(example,index) in form.code_examples" :key="index" class="editor-item"><div class="item-actions"><span>EXAMPLE {{ index+1 }}</span><button type="button" class="small-button danger" @click="form.code_examples.splice(index,1)">Remove</button></div><div class="editor-fields"><label class="field">Title<input v-model="example.title" required /></label><label class="field">Language<select v-model="example.language"><option v-for="lang in ['php','sql','bash','javascript','xml','css','blade']" :key="lang">{{ lang }}</option></select></label></div><label class="field">Source code<textarea v-model="example.source_code" class="mono-field" rows="12" spellcheck="false" required /></label><label class="field">Documented output<textarea v-model="example.expected_output" class="mono-field" rows="3" /></label><label class="field">Walkthrough<textarea v-model="example.explanation" rows="4" required /></label></div></section><section class="panel editor-section"><div class="section-heading"><h2>Practice exercises</h2><button type="button" class="small-button" @click="form.exercises.push({title:'',instructions:'',solution:''})">Add exercise +</button></div><div v-for="(exercise,index) in form.exercises" :key="index" class="editor-item"><div class="item-actions"><span>EXERCISE {{ index+1 }}</span><button type="button" class="small-button danger" @click="form.exercises.splice(index,1)">Remove</button></div><label class="field">Title<input v-model="exercise.title" required /></label><label class="field">Instructions<textarea v-model="exercise.instructions" required rows="4" /></label><label class="field">Suggested solution<textarea v-model="exercise.solution" required rows="4" /></label></div></section><section class="panel editor-section"><div class="section-heading"><div><h2>Knowledge check</h2><p v-if="locked">Locked: learners have submitted attempts. Create a new lesson to revise the quiz.</p></div><button v-if="!locked" type="button" class="small-button" @click="form.quiz = form.quiz ? null : {title:'Knowledge check',questions:[{prompt:'',explanation:'',options:['','','',''],correct_index:0}]}">{{ form.quiz ? 'Remove quiz' : 'Add quiz +' }}</button></div><fieldset v-if="form.quiz" :disabled="locked"><label class="field">Quiz title<input v-model="form.quiz.title" required /></label><div v-for="(question,index) in form.quiz.questions" :key="index" class="editor-item"><div class="item-actions"><span>QUESTION {{ index + 1 }}</span><button v-if="!locked" type="button" class="small-button danger" @click="form.quiz.questions.splice(index,1)">Remove</button></div><label class="field">Question<textarea v-model="question.prompt" required rows="2" /></label><label v-for="(_,optionIndex) in question.options" :key="optionIndex" class="field">Option {{ optionIndex+1 }}<input v-model="question.options[optionIndex]" required /></label><label class="field">Correct option<select v-model="question.correct_index"><option v-for="(_,optionIndex) in question.options" :key="optionIndex" :value="optionIndex">Option {{ optionIndex+1 }}</option></select></label><label class="field">Explanation<textarea v-model="question.explanation" required rows="3" /></label></div><button v-if="!locked" type="button" class="small-button" @click="addQuestion">Add question +</button></fieldset></section><div class="editor-actions"><label class="checkbox-label"><input v-model="form.is_published" type="checkbox" /> Publish lesson</label><div class="flex gap-3 items-center"><Link v-if="source" :href="route('lessons.show', source.slug)" class="text-link">Preview ↗</Link><button class="button primary" :disabled="form.processing">{{ form.processing ? 'Saving…' : 'Save lesson' }}<Icon name="check" size="16" /></button></div></div></form></AcademyLayout></template>
